import sys

class AssignmentManager:
    def __init__(self):
        self.todo_list = {}
        self.history = []

    def set(self, ai, xi):
        self.todo_list[ai] = xi
        self.history.append(('set', ai, xi))

    def remove(self, ai):
        if ai in self.todo_list:
            del self.todo_list[ai]
            self.history.append(('remove', ai))

    def query(self, ai):
        if ai in self.todo_list:
            xi = self.todo_list[ai]
            count = sum(1 for key, value in self.todo_list.items() if value < xi)
            return count
        else:
            return -1

    def undo(self, di):
        for _ in range(di):
            if self.history:
                last_op = self.history.pop()
                if last_op[0] == 'set':
                    del self.todo_list[last_op[1]]
                elif last_op[0] == 'remove':
                    self.todo_list[last_op[1]] = last_op[2]

def main():
    q = int(sys.stdin.readline().strip())
    manager = AssignmentManager()

    for _ in range(q):
        line = sys.stdin.readline().strip().split()
        op = line[0]

